const state = items[0]?.json?.state || items[0]?.json || {};
const now = new Date().toISOString();
const facts = state.research?.financials?.raw_us_gaap_facts || {};
const years = [2025, 2024, 2023];
function rowsFor(tags) {
  for (const tag of tags) {
    const fact = facts[tag];
    if (!fact?.units) continue;
    const rows = Object.values(fact.units).flat().filter((r) => r && r.val !== undefined);
    if (rows.length) return { tag, rows };
  }
  return { tag: tags[0], rows: [] };
}
const tags = {
  revenue: ['RevenueFromContractWithCustomerExcludingAssessedTax','Revenues','SalesRevenueNet'],
  gross_profit: ['GrossProfit'],
  operating_income: ['OperatingIncomeLoss'],
  net_income: ['NetIncomeLoss','ProfitLoss'],
  ocf: ['NetCashProvidedByUsedInOperatingActivities','NetCashProvidedByUsedInOperatingActivitiesContinuingOperations'],
  capex: ['PaymentsToAcquirePropertyPlantAndEquipment','PaymentsToAcquireProductiveAssets'],
  current_assets: ['AssetsCurrent'],
  current_liabilities: ['LiabilitiesCurrent'],
  interest_expense: ['InterestExpenseNonOperating','InterestExpense'],
  debt: ['LongTermDebtAndFinanceLeaseObligationsNoncurrent','LongTermDebtNoncurrent','LongTermDebtAndFinanceLeaseObligationsCurrent','ShortTermBorrowings'],
  equity: ['StockholdersEquity','StockholdersEquityIncludingPortionAttributableToNoncontrollingInterest'],
  assets: ['Assets'],
  liabilities: ['Liabilities']
};
function latestAnnual(metric, fy) {
  const found = rowsFor(tags[metric] || [metric]);
  const row = found.rows.filter((r) => r.form === '10-K' && Number(r.fy) === Number(fy)).sort((a,b) => String(a.end || '').localeCompare(String(b.end || '')) || String(a.filed || '').localeCompare(String(b.filed || ''))).at(-1);
  return row ? { value: Number(row.val), source_name: `SEC EDGAR Company Facts:${found.tag}`, source_url: state.research?.financials?.source_url || '', source_date: row.filed || now, period: `FY${fy}`, confidence: 'HIGH' } : null;
}
function calc(inputs, fn, formula) {
  if (inputs.some((x) => !x || x.value === undefined || Number.isNaN(Number(x.value)))) return null;
  const denom = inputs[1]?.value;
  if (inputs.length > 1 && Number(denom) === 0) return null;
  return { value: fn(...inputs.map((x) => Number(x.value))), formula, source_name: inputs.map((x) => x.source_name).join(' + '), source_url: inputs.map((x) => x.source_url).filter(Boolean).join(' | '), source_date: inputs.map((x) => x.source_date).filter(Boolean).sort().at(-1) || now, confidence: inputs.every((x) => x.confidence === 'HIGH') ? 'HIGH' : 'MEDIUM' };
}
function yearRatios(fy) {
  const revenue = latestAnnual('revenue', fy);
  const gross = latestAnnual('gross_profit', fy);
  const op = latestAnnual('operating_income', fy);
  const net = latestAnnual('net_income', fy);
  const ocf = latestAnnual('ocf', fy);
  const capex = latestAnnual('capex', fy);
  const ca = latestAnnual('current_assets', fy);
  const cl = latestAnnual('current_liabilities', fy);
  const interest = latestAnnual('interest_expense', fy);
  const debt = latestAnnual('debt', fy);
  const equity = latestAnnual('equity', fy);
  const assets = latestAnnual('assets', fy);
  const liabilities = latestAnnual('liabilities', fy);
  const fcf = calc([ocf, capex], (a,b) => a - b, 'Operating cash flow - capital expenditures');
  const capitalEmployed = calc([assets, cl], (a,b) => a - b, 'Total assets - current liabilities');
  return {
    period: `FY${fy}`,
    debt_to_equity: calc([debt, equity], (a,b) => a / b, 'Total debt / total equity'),
    fcf_to_revenue: calc([fcf, revenue], (a,b) => a / b, 'Free cash flow / revenue'),
    current_ratio: calc([ca, cl], (a,b) => a / b, 'Current assets / current liabilities'),
    interest_coverage: calc([op, interest], (a,b) => a / Math.abs(b), 'Operating income / interest expense'),
    roce: calc([op, capitalEmployed], (a,b) => a / b, 'Operating income / capital employed'),
    gross_margin: calc([gross, revenue], (a,b) => a / b, 'Gross profit / revenue'),
    operating_margin: calc([op, revenue], (a,b) => a / b, 'Operating income / revenue'),
    net_margin: calc([net, revenue], (a,b) => a / b, 'Net income / revenue')
  };
}
const ratioNames = [
  ['debt_to_equity','Debt to Equity'], ['fcf_to_revenue','Free Cash Flow to Revenue'], ['current_ratio','Current Ratio'], ['interest_coverage','Interest Coverage'], ['roce','Return on Capital Employed'], ['gross_margin','Gross Margin'], ['operating_margin','Operating Margin'], ['net_margin','Net Margin']
];
const annual = years.map(yearRatios);
function display(item) { return item ? String(Number(item.value).toFixed(4)) : 'N/A'; }
const markdown = ['## Section 5: Ratio Dashboard', '', '| Ratio | ' + annual.map((p) => p.period).join(' | ') + ' | Formula |', '|---|' + annual.map(() => '---').join('|') + '|---|', ...ratioNames.map(([key,label]) => `| ${label} | ${annual.map((p) => display(p[key])).join(' | ')} | ${(annual.find((p) => p[key])?.[key]?.formula) || 'N/A - required source line items missing'} |`), '', 'Notes: Ratios use SEC EDGAR source line items where available. N/A means one or more required source inputs were missing for that period. Quarterly ratios are prepared by the snapshot agent when quarterly source facts are available; this dashboard emphasizes the last three fiscal years.'].join('\n');
state.ratio_dashboard = { generated_at: now, annual, markdown, formulas: Object.fromEntries(ratioNames.map(([key,label]) => [key, annual.find((p) => p[key])?.[key]?.formula || 'N/A'])) };
state.sections = state.sections || {};
state.sections.s5_ratios = markdown;
state.audit_log = state.audit_log || [];
state.audit_log.push({ timestamp: now, workflow_name: 'WF_RATIO_DASHBOARD', status: 'OK', message: 'Founder ratio dashboard prepared with formulas and N/A handling.' });
return [{ json: state }];

